// Python int(str) parsing semantics, producing a BigInt.
// Rules: surrounding whitespace stripped, optional +/- sign, decimal digits,
// single underscores allowed between digits. Arbitrary precision via BigInt.

export class PyIntError extends Error {
  constructor(value) {
    super(`invalid literal for int() with base 10: ${value}`);
    this.name = 'PyIntError';
    this.value = value;
  }
}

export function parsePyInt(str) {
  // Python str.strip() removes leading/trailing whitespace.
  const stripped = str.replace(/^\s+|\s+$/g, '');
  const m = /^([+-]?)(\d(?:_?\d)*)$/.exec(stripped);
  if (!m) {
    throw new PyIntError(str);
  }
  const digits = m[2].replace(/_/g, '');
  // BigInt('-0') is 0n, matching Python int('-0') == 0.
  return BigInt((m[1] === '-' ? '-' : '') + digits);
}

// Byte strings are represented as plain JS strings with latin1 semantics:
// each char code (0-255) is one byte. No typed arrays anywhere.

// Mimics Python's str.encode('ascii'): every char code must be <= 127,
// otherwise raises (the caller turns this into the UnicodeEncodeError path).
export class AsciiEncodeError extends Error {
  constructor(ch, position, code) {
    super('UnicodeEncodeError');
    this.name = 'AsciiEncodeError';
    this.ch = ch;
    this.position = position;
    this.code = code;
  }
}

export function asciiEncode(str) {
  for (let i = 0; i < str.length; i++) {
    const code = str.charCodeAt(i);
    if (code > 127) {
      throw new AsciiEncodeError(str[i], i, code);
    }
  }
  // All codes <= 127, so the string is already valid latin1 "bytes".
  return str;
}

// Python repr() of a single character, used inside UnicodeEncodeError text:
// '\xe9' style for <=0xff, '\uXXXX' for <=0xffff, '\UXXXXXXXX' above.
export function pyCharRepr(code) {
  if (code <= 0xff) return "'\\x" + code.toString(16).padStart(2, '0') + "'";
  if (code <= 0xffff) return "'\\u" + code.toString(16).padStart(4, '0') + "'";
  return "'\\U" + code.toString(16).padStart(8, '0') + "'";
}

// Python bytes repr: b'...'
// Default quote is '; if data contains ' but not ", use " instead.
// Escape: backslash, the active quote, \n \r \t; printable ASCII 0x20-0x7E
// stays literal; everything else becomes \xNN (lowercase hex, two digits).
export function bytesRepr(s) {
  const hasSingle = s.indexOf("'") !== -1;
  const hasDouble = s.indexOf('"') !== -1;
  const quote = hasSingle && !hasDouble ? '"' : "'";
  let out = 'b' + quote;
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    const code = s.charCodeAt(i);
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += '\\' + quote;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else if (code >= 0x20 && code <= 0x7e) out += ch;
    else out += '\\x' + code.toString(16).padStart(2, '0');
  }
  return out + quote;
}

// Python repr of the decoded nested structure: latin1 strings render as
// bytes reprs, BigInts as decimal integers, arrays as Python lists.

import { bytesRepr } from './pybytes.mjs';

export function pyRepr(value) {
  if (typeof value === 'string') return bytesRepr(value);
  if (typeof value === 'bigint') return value.toString();
  if (Array.isArray(value)) {
    return '[' + value.map(pyRepr).join(', ') + ']';
  }
  throw new TypeError('pyRepr: unsupported value type');
}

// Python repr() of a str (used by argparse for invalid int values):
// single quotes by default, double quotes if the string contains ' but not ".
export function pyStrRepr(s) {
  const hasSingle = s.indexOf("'") !== -1;
  const hasDouble = s.indexOf('"') !== -1;
  const quote = hasSingle && !hasDouble ? '"' : "'";
  let out = quote;
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    const code = s.charCodeAt(i);
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += '\\' + quote;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else if (code >= 0x20 && code <= 0x7e) out += ch;
    else if (code <= 0xff) out += '\\x' + code.toString(16).padStart(2, '0');
    else if (code <= 0xffff) out += '\\u' + code.toString(16).padStart(4, '0');
    else out += '\\U' + code.toString(16).padStart(8, '0');
  }
  return out + quote;
}

// Bencode encode/decode over plain latin1 JS strings (no typed arrays).
// Value model: string = byte string, BigInt = integer, Array = list.

export function encode(value) {
  if (typeof value === 'string') {
    return value.length + ':' + value;
  }
  if (typeof value === 'bigint') {
    return 'i' + value.toString() + 'e';
  }
  if (Array.isArray(value)) {
    return 'l' + value.map(encode).join('') + 'e';
  }
  throw new TypeError('bencode.encode: unsupported value type');
}

export function decode(str) {
  let pos = 0;

  function parse() {
    const c = str[pos];
    if (c === 'i') {
      const end = str.indexOf('e', pos);
      if (end === -1) throw new Error('bencode: unterminated integer');
      const n = BigInt(str.slice(pos + 1, end));
      pos = end + 1;
      return n;
    }
    if (c === 'l') {
      pos++;
      const items = [];
      while (str[pos] !== 'e') {
        if (pos >= str.length) throw new Error('bencode: unterminated list');
        items.push(parse());
      }
      pos++;
      return items;
    }
    if (c >= '0' && c <= '9') {
      const colon = str.indexOf(':', pos);
      if (colon === -1) throw new Error('bencode: missing colon');
      const len = parseInt(str.slice(pos, colon), 10);
      pos = colon + 1;
      if (pos + len > str.length) throw new Error('bencode: string overrun');
      const out = str.slice(pos, pos + len);
      pos += len;
      return out;
    }
    throw new Error('bencode: invalid token at position ' + pos);
  }

  const value = parse();
  if (pos !== str.length) throw new Error('bencode: trailing data');
  return value;
}

// Minimal reimplementation of the Python argparse behavior used by test6:
// two required options --a (str) and --b (int), plus -h/--help.

import { parsePyInt, PyIntError } from './pyint.mjs';
import { pyStrRepr } from './pyrepr.mjs';

function basename(p) {
  const parts = String(p).split('/');
  return parts[parts.length - 1];
}

// argparse treats a token starting with '-' as an option string unless it
// looks like a negative number (the parser has no number-like options).
function looksLikeOption(tok) {
  if (tok.length <= 1 || tok[0] !== '-') return false;
  return !/^-\d/.test(tok) && !/^-\.\d/.test(tok);
}

export function parseArgs(argv) {
  const prog = basename(argv[1] || 'test6.mjs');
  const tokens = argv.slice(2);
  const usage = `usage: ${prog} [-h] --a A --b B`;

  const fail = (msg) => {
    process.stderr.write(usage + '\n' + prog + ': error: ' + msg + '\n');
    process.exit(2);
  };

  const printHelp = () => {
    process.stdout.write(
      usage + '\n' +
      '\n' +
      'options:\n' +
      '  -h, --help  show this help message and exit\n' +
      '  --a A\n' +
      '  --b B\n'
    );
    process.exit(0);
  };

  let a;
  let b;
  const extras = [];

  for (let i = 0; i < tokens.length; i++) {
    const tok = tokens[i];
    if (tok === '-h' || tok === '--help') {
      printHelp();
    }
    if (tok.startsWith('--')) {
      let name = tok;
      let value;
      let hasValue = false;
      const eq = tok.indexOf('=');
      if (eq !== -1) {
        name = tok.slice(0, eq);
        value = tok.slice(eq + 1);
        hasValue = true;
      }
      if (name === '--a' || name === '--b') {
        if (!hasValue) {
          if (i + 1 >= tokens.length || looksLikeOption(tokens[i + 1])) {
            fail(`argument ${name}: expected one argument`);
          }
          value = tokens[++i];
        }
        if (name === '--a') {
          a = value;
        } else {
          try {
            b = parsePyInt(value);
          } catch (e) {
            if (e instanceof PyIntError) {
              fail(`argument --b: invalid int value: ${pyStrRepr(value)}`);
            }
            throw e;
          }
        }
      } else {
        extras.push(tok);
      }
    } else {
      extras.push(tok);
    }
  }

  const missing = [];
  if (a === undefined) missing.push('--a');
  if (b === undefined) missing.push('--b');
  if (missing.length > 0) {
    fail('the following arguments are required: ' + missing.join(', '));
  }
  if (extras.length > 0) {
    fail('unrecognized arguments: ' + extras.join(' '));
  }

  return { a, b };
}

